using UnityEditor;using UnityEngine;using SoulboundLegends.Siege;[CustomEditor(typeof(SiegeWorldGenerator))]public class SiegeWorldGeneratorEditor:Editor{public override void OnInspectorGUI(){var g=(SiegeWorldGenerator)target;DrawDefaultInspector();EditorGUILayout.Space(10);EditorGUILayout.LabelField("FINAL SIEGE WORLD BUILDER",EditorStyles.boldLabel);if(GUILayout.Button("AUTO-CREATE ALL CONNECTION SLOTS",GUILayout.Height(30))){g.AutoCreateAllConnectionSlots();EditorUtility.SetDirty(g);}if(GUILayout.Button("VALIDATE SIEGE CONNECTIONS",GUILayout.Height(30))){g.ValidateConnections(out var r);Debug.Log(r);}if(GUILayout.Button("GENERATE FINAL SIEGE WORLD",GUILayout.Height(40))){g.GenerateFinalSiegeWorld();EditorUtility.SetDirty(g);Debug.Log(g.lastGenerationReport);}EditorGUILayout.HelpBox("Siege generation is specialized for fortified, destructible strongholds. CS capture/round rules and BR rules are not included.",MessageType.Info);}}